{
  "name": "opencode-jev-compaction",
  "version": "0.3.0",
  "description": "opencode plugins that shrink context by deleting provably-stale tool calls and truncating the rest, deterministically first, with an optional local Laya backend.",
  "type": "module",
  "license": "MIT",
  "author": "JLegends",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JLegends/opencode-jev-compaction.git"
  },
  "homepage": "https://github.com/JLegends/opencode-jev-compaction#readme",
  "bugs": {
    "url": "https://github.com/JLegends/opencode-jev-compaction/issues"
  },
  "exports": {
    "./server": {
      "import": "./src/server.ts"
    },
    "./tui": {
      "import": "./src/tui.js"
    }
  },
  "files": [
    "src",
    "README.md",
    "LICENSE",
    "NOTICE",
    "scripts"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "compaction",
    "context",
    "tokens",
    "jev",
    "typesafe",
    "cost"
  ],
  "engines": {
    "opencode": ">=1.18.31"
  },
  "peerDependencies": {
    "@opentui/solid": ">=0.4.5",
    "solid-js": "^1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "scripts": {
    "check": "node --check src/tui.js && bun build src/server.ts --target node --outfile .check.js && rm -f .check.js",
    "report": "node scripts/report.mjs"
  }
}
